_POLICY = None

_FIRST = {
    "BAKERY": "BASE",
    "BRUNCH_SPOT": "BASE",
    "PET_CAFE": "BASE",
    "FARMERS_MARKET": "FARM",
    "ICE_CREAM_SHOP": "ICE",
    "PIZZA_SHOP": "PIZZA",
    "SMOOTHIE_SHOP": "SMOOTH",
    "YARN_STORE": "YARN",
}

# Selected only when both development splits improved or did not regress.
_DAY6 = {
    ("ICE_CREAM_SHOP", "YARN_STORE"): "SMOOTH",
    ("PET_CAFE", "ICE_CREAM_SHOP"): "FARM",
    ("SMOOTHIE_SHOP", "PIZZA_SHOP"): "ICE",
    ("SMOOTHIE_SHOP", "SMOOTHIE_SHOP"): "ICE",
}

def _get(obj, key, default=None):
    try:
        return obj.get(key, default)
    except Exception:
        try:
            return getattr(obj, key)
        except Exception:
            return default

def _load():
    global _POLICY
    if _POLICY is None:
        _POLICY = json.loads(zlib.decompress(base64.b85decode(_POLICY_B85)).decode("utf-8"))
    return _POLICY

def _clone(a):
    if not isinstance(a, dict):
        return {"farmer":["PASS"],"hands":[],"market":[]}
    farmer=a.get("farmer",["PASS"]);hands=a.get("hands",[]);market=a.get("market",[])
    return {
        "farmer": list(farmer) if isinstance(farmer,list) else ["PASS"],
        "hands": [list(x) for x in hands if isinstance(x,list)] if isinstance(hands,list) else [],
        "market": [list(x) for x in market if isinstance(x,list)] if isinstance(market,list) else [],
    }

def _hands_count(obs, pid):
    try:
        farms=_get(obs,"farms",[]) or []
        return len(_get(farms[pid],"hands",[]) or []) if len(farms)>pid else 0
    except Exception:
        return 0

def agent(obs, configuration=None):
    try:
        policy=_load()
        pid=int(_get(obs,"player",0) or 0)
        raw_step=_get(obs,"step",None)
        if raw_step is None:
            raw_step=int(_get(obs,"day",0) or 0)*24+int(_get(obs,"hour",0) or 0)
        step=int(raw_step);t=step+1
        if t>=720:
            return {"farmer":["PASS"],"hands":[["PASS"] for _ in range(_hands_count(obs,pid))],"market":[]}
        town=_get(obs,"town",{}) or {}
        shops=_get(town,"unlocked_shops",[]) or []
        if t<=72:
            label="BASE"
        else:
            first=shops[0] if shops else None
            label=_FIRST.get(first,"BASE")
            if t>=145 and len(shops)>=2:
                label=_DAY6.get((shops[0],shops[1]),label)
        seq=policy.get(label) or policy["BASE"]
        return _clone(seq[t])
    except Exception:
        try:
            pid=int(_get(obs,"player",0) or 0)
        except Exception:
            pid=0
        return {"farmer":["PASS"],"hands":[["PASS"] for _ in range(_hands_count(obs,pid))],"market":[]}
